const ELEMENT_PROP_KEYS = new Set(["theme","tag","label","headline","highlight","subhead","align","exit","stagger","fontWeight","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  tag: "New",
  label: "Captions",
  headline: "Captions that move with every word.",
  highlight: "every word",
  subhead: "31 transcript-driven caption styles, ready to drop into any video.",
  align: "left",
  exit: true,
  stagger: 2,
  fontWeight: 500,
  accent: "#3B5BFD",
  fontFamily: "Geist",
  scale: 1,
  delay: 0,
  speed: 1,
};

type FeatureHeadlineElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof FeatureHeadlineBase>;

const FeatureHeadlineInner = forwardRef<
  HTMLDivElement,
  FeatureHeadlineElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<FeatureHeadline>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <FeatureHeadlineBase
          {...(componentProps as unknown as ComponentProps<typeof FeatureHeadlineBase>)}
        />
      </div>
    </Sequence>
  );
});

export const FeatureHeadline = Interactive.withSchema({
  Component: FeatureHeadlineInner,
  componentName: "<FeatureHeadline>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
